import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')
SECRET_SALT = os.environ.get('SECRET_SALT', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        details TEXT,
        ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_api_key(api_key):
    """Verify API key against database. Returns user row or None."""
    db = get_db()
    # Note: api_key is a hex string, validated by middleware
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
    return user

@app.before_request
def check_auth():
    if request.endpoint in ('health', 'static'):
        return None
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'Missing API key'}), 401
    user = verify_api_key(api_key)
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403
    g.current_user = user

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/users/search')
def search_users():
    """Search users by various fields. Supports flexible filtering."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Restrict searchable fields to prevent accessing sensitive columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query with validated field name and user-supplied value
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>/notes', methods=['POST'])
def add_note(user_id):
    """Add a note/comment to a user profile."""
    data = request.get_json()
    note = data.get('note', '')
    db = get_db()
    db.execute(
        'INSERT INTO audit_log (action, user_id, details) VALUES (?, ?, ?)',
        ('note_added', user_id, note)
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/api/export')
def export_data():
    """Export audit log as JSON. Admin only."""
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    db = get_db()
    logs = db.execute('SELECT * FROM audit_log ORDER BY ts DESC LIMIT 1000').fetchall()
    return jsonify({'logs': [dict(r) for r in logs]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
